from .base_page import BasePagefrom locators import AddToBasketLocatorsclass ProductPage(BasePage):    def should_be_check_to_add_page(self):        self.add_to_basket_check_url()        self.add_to_basket_click()        self.click_to_button()    def add_to_basket_check_url(self):        #@allure.step("Проверка корректности URL страницы товара")        assert 'the-shellcoders-handbook_209/?promo=newYear' in self.browser.current_url, 'ProductAdd url is not correct'        print("\n[OK] URL проверен успешно")    def add_to_basket_click(self):        assert self.is_element_present(*AddToBasketLocators.BUTTON_BASKET), 'Basket button is not presented'        print("\n[OK] Кнопка отображается")    def click_to_button(self):       button_add = self.browser.find_element(*AddToBasketLocators.BUTTON_BASKET)       button_add.click()       print("\n[OK] Кнопка нажимается")    #Проверить почему вторая проверка не пашет